//frontend/src/store/productStore.js
import { reactive, toRefs } from "vue";
import {
  createProduct,
  getAllProducts,
  getProductById,
  updateProduct,
  deleteProduct,
} from "@/services/productService.js"; // 引入服务层

// 创建一个可反应的状态对象
const state = reactive({
  products: [],
  error: null,
});

// action 用于处理异步操作和状态更新
const actions = {
  async fetchProducts() {
    state.error = null; // 清空之前的错误信息
    try {
      const response = await getAllProducts();
      state.products = response; // 更新产品列表
    } catch (error) {
      state.error = error.message; // 处理错误
    }
  },

  async fetchProductById(id) {
    state.error = null; // 清空之前的错误信息
    try {
      const response = await getProductById(id);
      state.currentProduct = response; // 更新当前产品
    } catch (error) {
      state.error = error.message; // 处理错误
    }
  },

  async addProduct(productData) {
    state.error = null; // 清空之前的错误信息
    try {
      const response = await createProduct(productData);
      state.products.push(response); // 将新产品添加到列表
    } catch (error) {
      state.error = error.message; // 处理错误
    }
  },

  async updateProduct(id, updatedData) {
    state.error = null; // 清空之前的错误信息
    try {
      const response = await updateProduct(id, updatedData);
      const index = state.products.findIndex((product) => product.id === id);
      if (index !== -1) {
        state.products[index] = response; // 更新产品列表中的产品
      }
    } catch (error) {
      state.error = error.message; // 处理错误
    }
  },

  async deleteProduct(id) {
    state.error = null; // 清空之前的错误信息
    try {
      await deleteProduct(id);
      state.products = state.products.filter((product) => product.id !== id); // 从列表中删除产品
    } catch (error) {
      state.error = error.message; // 处理错误
    }
  },
};

// 导出状态和 actions
export default {
  ...toRefs(state), // 解构响应状态为 refs，以便在组件中使用
  actions,
};
